// 环境隔离：同一份代码按环境加载不同配置，互不串门
const configs = {
  dev: { db: "localhost:5432", log: "debug" },
  staging: { db: "stg.db:5432", log: "info" },
  prod: { db: "prod.db:5432", log: "warn" },
};

function loadConfig(env) {
  const c = configs[env] ?? configs.dev; // 未知环境回退到最安全的 dev
  return `env=${env} db=${c.db} log=${c.log}`;
}

console.log(loadConfig("prod"));
console.log(loadConfig("dev"));
console.log(loadConfig("unknown")); // 回退到 dev，不读生产库
